break terminates the entire loop, while continue skips the current iteration and continues with the next one.

code:
// break example
for (let i = 0; i < 5; i++) {
  if (i === 2) break;
  console.log(i); // logs 0, 1
}

// continue example
for (let i = 0; i < 5; i++) {
  if (i === 2) continue;
  console.log(i); // logs 0, 1, 3, 4
}

real example:
In a test filtering valid errors, continue skips non-error entries while break stops entirely when a critical error is found.

Use a for loop with a break condition inside.

code:
function printNumbers(limit) {
  for (let i = 1; i <= limit; i++) {
    if (i % 3 === 0 && i % 5 === 0) {
      break;
    }
    console.log(i);
  }
}
printNumbers(20);

