Use a for loop, push positive numbers, and break when a negative number (sentinel) is found.

code:
function getPositiveNumbers(numbers) {
  const result = [];
  for (const num of numbers) {
    if (num < 0) break;
    if (num > 0) result.push(num);
  }
  return result;
}
console.log(getPositiveNumbers([1, 2, -1, 3, 4])); // [1, 2]

