Use a labeled break or a flag to exit both loops when the target is found.

code:
function findInMatrix(matrix, target) {
  for (let i = 0; i < matrix.length; i++) {
    for (let j = 0; j < matrix[i].length; j++) {
      if (matrix[i][j] === target) {
        return [i, j];
      }
    }
  }
  return null;
}
const matrix = [[1, 2], [3, 4], [5, 6]];
console.log(findInMatrix(matrix, 4)); // [1, 1]
console.log(findInMatrix(matrix, 7)); // null

