Use a for loop, try/catch, and break when the function succeeds.

code:
function retryOperation(fn, attempts) {
  for (let i = 0; i < attempts; i++) {
    try {
      return fn();
    } catch {
      if (i === attempts - 1) throw new Error('All attempts failed');
    }
  }
}
const successOnSecond = () => {
  static count = 0;
  count++;
  if (count === 1) throw new Error('fail');
  return 'success';
};
console.log(retryOperation(successOnSecond, 3)); // 'success'

