Use a for loop, add to sum, and break when a negative number is found.

code:
function sumUntilNegative(numbers) {
  let sum = 0;
  for (const num of numbers) {
    if (num < 0) break;
    sum += num;
  }
  return sum;
}
console.log(sumUntilNegative([1, 2, 3, -1, 4, 5])); // 6
console.log(sumUntilNegative([1, 2, 3])); // 6

