Use for...of loop with break when condition is met.

code:
function findFirstOverThreshold(numbers, threshold) {
  for (const num of numbers) {
    if (num > threshold) return num;
  }
  return undefined;
}
console.log(findFirstOverThreshold([1, 3, 5, 7, 9], 4)); // 5
console.log(findFirstOverThreshold([1, 2, 3], 10)); // undefined

